mapper.select:
SELECT

	
		${page.fields}
	
	
		,LWHH,ATTR_TYPE
	

FROM (SELECT
SUM(CASE WHEN PZ.ACTIVE_SYS = 4 THEN SUM ELSE 0 END) ASUM,
SUM(CASE WHEN PZ.ACTIVE_SYS = 2 THEN SUM ELSE 0 END) BSUM,
PZ.REPORT_TIME,
PZ.SERVICE,
pz.LWHH,
pz.ATTR_TYPE
FROM DJ_LWHH_TYPE_REPORT PZ
GROUP BY PZ.LWHH,PZ.ATTR_TYPE, PZ.SERVICE, PZ.REPORT_TIME
) DJ_LWHH_TYPE_REPORT

	
		AND REPORT_TIME >= to_date(#{searchReportStartTime},'yyyy-MM-dd HH24:mi:ss')
	
	
		AND REPORT_TIME < to_date(#{searchReportEndTime},'yyyy-MM-dd HH24:mi:ss')
	
	
		AND ATTR_TYPE =#{searchAttrType}
	
	
		AND LWHH =#{searchLwhh}
	
	
		AND SERVICE =#{searchService}
	


	
		ORDER BY ${page.orderBy}

SELECT
${page.fields}
,LWHH,TAG
FROM (SELECT SUM(CASE WHEN PZ.ACTIVE_SYS = 4 THEN SUM ELSE 0 END) ASUM, SUM(CASE WHEN PZ.ACTIVE_SYS = 2 THEN SUM ELSE 0 END) BSUM, PZ.REPORT_TIME, PZ.SERVICE, pz.LWHH, pz.TAG FROM DJ_LWHH_TAG_REPORT PZ GROUP BY PZ.LWHH,PZ.TAG, PZ.SERVICE, PZ.REPORT_TIME ) DJ_LWHH_TAG_REPORT
AND REPORT_TIME >= to_date(#{searchReportStartTime},'yyyy-MM-dd HH24:mi:ss')
AND REPORT_TIME < to_date(#{searchReportEndTime},'yyyy-MM-dd HH24:mi:ss')
AND TAG in (${searchTag})
AND LWHH =#{searchLwhh}
AND SERVICE =#{searchService}
ORDER BY ${page.orderBy}

SELECT
${page.fields}
,SRC_PROVINCE,TAG
FROM (SELECT SUM(CASE WHEN PZ.ACTIVE_SYS = 4 THEN SUM ELSE 0 END) ASUM, SUM(CASE WHEN PZ.ACTIVE_SYS = 2 THEN SUM ELSE 0 END) BSUM, PZ.REPORT_TIME, PZ.SERVICE, pz.SRC_PROVINCE, pz.TAG FROM DJ_SRCIP_DOMESTIC_TAG_REPORT PZ GROUP BY PZ.SRC_PROVINCE,PZ.TAG, PZ.SERVICE, PZ.REPORT_TIME ) DJ_SRCIP_DOMESTIC_TAG_REPORT
AND REPORT_TIME >= to_date(#{searchReportStartTime},'yyyy-MM-dd HH24:mi:ss')
AND REPORT_TIME < to_date(#{searchReportEndTime},'yyyy-MM-dd HH24:mi:ss')
AND TAG in (${searchTag})
AND SRC_PROVINCE =#{searchSrcProvince}
AND SERVICE =#{searchService}
ORDER BY ${page.orderBy}

SELECT

	
		${page.fields}
	
	
		,SRC_PROVINCE,ATTR_TYPE
	

FROM (SELECT
SUM(CASE WHEN PZ.ACTIVE_SYS = 4 THEN SUM ELSE 0 END) ASUM,
SUM(CASE WHEN PZ.ACTIVE_SYS = 2 THEN SUM ELSE 0 END) BSUM,
PZ.REPORT_TIME,
PZ.SERVICE,
pz.SRC_PROVINCE,
pz.ATTR_TYPE
FROM DJ_SRCIP_DOMESTIC_TYPE_REPORT PZ
GROUP BY PZ.SRC_PROVINCE,PZ.ATTR_TYPE, PZ.SERVICE, PZ.REPORT_TIME
) DJ_SRCIP_DOMESTIC_TYPE_REPORT

	
		AND REPORT_TIME >= to_date(#{searchReportStartTime},'yyyy-MM-dd HH24:mi:ss')
	
	
		AND REPORT_TIME < to_date(#{searchReportEndTime},'yyyy-MM-dd HH24:mi:ss')
	
	
		AND ATTR_TYPE =#{searchAttrType}
	
	
		AND SRC_PROVINCE =#{searchSrcProvince}
	
	
		AND SERVICE =#{searchService}
	


	
		ORDER BY ${page.orderBy}
